'use strict';
const $ = s => document.querySelector(s);
const escapeHTML = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('ru-RU').format(n) + ' ₽';
const services = [
{id:'diagnostics',icon:'⌁',title:'Диагностика автомобиля',description:'Проверим системы и найдём причину неисправности. Объясним результат простыми словами.',price:1500,duration:60},
{id:'oil',icon:'◒',title:'Замена масла и фильтра',description:'Подберём масло для вашего двигателя и заменим фильтр. Расходные материалы отдельно.',price:1800,duration:60},
{id:'brakes',icon:'⊙',title:'Обслуживание тормозов',description:'Проверка и замена колодок, дисков и жидкости. Безопасность в каждой поездке.',price:3200,duration:120},
{id:'suspension',icon:'⤨',title:'Ремонт подвески',description:'Устраним стуки, проверим амортизаторы и вернём автомобилю плавность хода.',price:2500,duration:120},
{id:'tires',icon:'◎',title:'Шиномонтаж',description:'Сезонная смена колёс, балансировка и проверка давления. Цена за комплект.',price:2800,duration:60},
{id:'ac',icon:'❋',title:'Обслуживание кондиционера',description:'Диагностика, очистка и заправка системы для комфортной температуры в салоне.',price:3500,duration:120}];
const stages = ['Принят','Диагностика','В работе','Проверка','Готов'];
const image1 = 'assets/service.jpg';
const image2 = 'assets/car.jpg';
function initial(){return {version:1,phone:null,bookings:[],orders:[{id:'AA-2048',car:'Volkswagen Golf',plate:'А 248 МР · 77',year:'2019',stage:4,accepted:false,note:'Заменили масло и фильтр, проверили тормозную систему. Автомобиль прошёл финальную проверку и готов к выдаче.',works:[{title:'Замена моторного масла',price:1800,done:true},{title:'Масло и масляный фильтр',price:5400,done:true},{title:'Диагностика тормозов',price:1500,done:true}],photos:[{src:image1,caption:'Осмотр и проверка автомобиля',sample:true},{src:image2,caption:'Пример фотографии автомобиля',sample:true}],messages:[{sender:'staff',text:'Здравствуйте! Работы закончены, всё проверили. Фотоотчёт уже в вашем кабинете. Можете принять работу или задать мне вопрос.',time:'Сегодня, 14:32'}]},{id:'AA-2049',car:'Kia Rio',plate:'К 519 ОК · 77',year:'2021',stage:2,accepted:false,note:'Проверяем переднюю подвеску. После диагностики согласуем перечень работ.',works:[{title:'Диагностика подвески',price:1500,done:false}],photos:[],messages:[{sender:'staff',text:'Автомобиль в работе. Здесь появятся обновления и фотографии.',time:'Сегодня, 12:15'}]}]};}
let state; try{state=JSON.parse(localStorage.getItem('autoatelier-demo-v1'))||initial(); if(state.version!==1||!Array.isArray(state.orders))state=initial();}catch{state=initial();}
let role='client', selectedOrder='AA-2048', selectedSlot=null;
function save(){try{localStorage.setItem('autoatelier-demo-v1',JSON.stringify(state));}catch{toast('Недостаточно места для сохранения. Попробуйте фото меньшего размера.');}}
function order(){return state.orders.find(o=>o.id===selectedOrder)||state.orders[0];}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function now(){return new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}).format(new Date());}
function dateISO(offset=0){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const vals=Object.fromEntries(parts.map(p=>[p.type,p.value]));const d=new Date(`${vals.year}-${vals.month}-${vals.day}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10);}
function dateLabel(v){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Moscow'}).format(new Date(v+'T12:00:00Z'));}
function pageTop(title,subtitle){return `<div class="topline"><div><div class="eyebrow">ВАШ СЕРВИС. ВАШЕ СПОКОЙСТВИЕ.</div><h1>${title}</h1><p class="muted">${subtitle}</p></div><div class="switch" aria-label="Режим демонстрации"><button data-role="client" class="${role==='client'?'active':''}">Я клиент</button><button data-role="staff" class="${role==='staff'?'active':''}">Я сотрудник</button></div></div>`;}
function carSVG(){return `<svg viewBox="0 0 520 255" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Иллюстрация автомобиля"><defs><linearGradient id="paint" x1="0" y1="0" x2="0.2" y2="1"><stop stop-color="#fbfcf6"/><stop offset=".6" stop-color="#d6dccb"/><stop offset="1" stop-color="#9ba791"/></linearGradient><linearGradient id="glass"><stop stop-color="#263b31"/><stop offset="1" stop-color="#5d7363"/></linearGradient></defs><ellipse cx="285" cy="215" rx="217" ry="15" fill="#1b3229" opacity=".14"/><path d="M47 168 Q52 128 102 118 L168 57 Q196 44 322 55 L386 114 Q454 121 476 155 L484 184 Q482 204 450 207 L75 207 Q40 203 47 168" fill="url(#paint)" stroke="#acb9a2" stroke-width="2"/><path d="M120 117 L177 65 Q210 54 320 65 L368 117Z" fill="url(#glass)"/><path d="M239 61 L239 117M317 65L326 117" stroke="#d2d8c6" stroke-width="8"/><path d="M89 129 Q256 151 430 132M247 129L247 185M333 127L343 183" fill="none" stroke="#afbba6" stroke-width="2"/><path d="M63 147L106 143L98 158L57 161Z" fill="#eef4be"/><path d="M439 141L468 152L473 166L440 160Z" fill="#d9e4ce"/><path d="M414 172L477 181L472 192L412 187Z" fill="#314537"/><rect x="261" y="140" width="22" height="5" rx="2" fill="#798b73"/><rect x="168" y="141" width="22" height="5" rx="2" fill="#798b73"/><g fill="#27382e" stroke="#809178" stroke-width="3"><circle cx="129" cy="195" r="38"/><circle cx="391" cy="195" r="38"/></g><g fill="#c4cdb8" stroke="#8c9c82" stroke-width="6"><circle cx="129" cy="195" r="22"/><circle cx="391" cy="195" r="22"/></g><g stroke="#65795f" stroke-width="4"><path d="M129 173V217M107 195H151M113 180L145 210M113 210L145 180M391 173V217M369 195H413M375 180L407 210M375 210L407 180"/></g></svg>`;}
function carCard(o){return `<section class="card car-card"><div class="car-info"><div class="eyebrow">МОЙ АВТОМОБИЛЬ · ${o.id}</div><h2>${escapeHTML(o.car)}</h2><p><span class="plate">${escapeHTML(o.plate)}</span><span class="small muted">${o.year} год</span></p><span class="badge"><span class="dot"></span>${o.accepted?'Работа принята':o.stage===4?'Готов к выдаче':stages[o.stage]}</span></div><div class="car-art">${carSVG()}</div></section>`;}
function progress(o){return `<section class="card"><div class="row status-header"><div><h3>Статус ремонта</h3><p class="muted small">Все этапы — без лишних звонков</p></div><span class="estimate">${o.stage===4?'Можно забирать':'Обновлено '+now()}</span></div><div class="steps">${stages.map((s,i)=>`<div class="step ${i<o.stage?'done':i===o.stage?'current':''}"><i>${i<o.stage?'✓':i+1}</i>${s}</div>`).join('')}</div><div class="status-note"><span class="icon">${o.stage===4?'✓':'⌁'}</span><div><strong class="small">${o.stage===4?'Ваш автомобиль готов':'Обновление от мастера'}</strong><p>${escapeHTML(o.note)}</p></div></div></section>`;}
function photos(o,staff=false){return `<section class="card"><div class="row"><div><h3>Фотоотчёт о работе</h3><p class="muted small">${staff?'Добавьте результат и пояснение для клиента':'Посмотрите результат перед приёмкой'}</p></div><span class="badge">${o.photos.length} фото</span></div>${o.photos.length?`<div class="photos">${o.photos.map((p,i)=>`<div class="photo-wrap"><button class="photo full" data-photo="${i}">${p.sample?'<span class="photo-tag">ДЕМО-ФОТО</span>':''}<img src="${escapeHTML(p.src)}" alt="${escapeHTML(p.caption)}" loading="lazy"><span>${escapeHTML(p.caption)} ↗</span></button>${staff?`<button class="remove-photo" data-remove-photo="${i}" aria-label="Удалить фото">×</button>`:''}</div>`).join('')}</div>`:'<p class="notice">Мастер добавит фотографии после выполнения работ.</p>'}${staff?`<label>Описание фотографии<input id="photo-title" placeholder="Например: новые тормозные колодки" maxlength="120"></label><label>Загрузить фотографии<input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="tiny">До 8 фотографий на заказ, до 8 МБ на файл. Фото будут уменьшены для хранения в демо.</p>`:o.accepted?'<div class="accepted">✓ Работа принята. Спасибо за доверие!</div>':`<div class="accept-row"><button class="primary" id="accept" ${o.stage!==4?'disabled':''}>✓ Принять работу</button><button class="secondary" id="ask">Задать вопрос ↗</button></div><p class="tiny" style="margin-top:12px">${o.stage===4?'Принимайте работу после ознакомления с результатом. Это тестовая приёмка без оплаты.':'Приёмка станет доступна после завершения ремонта.'}</p>`}</section>`;}
function chat(o){return `<section class="card chat-card" id="chat-card"><div class="person"><div class="avatar">${role==='staff'?'К':'А'}</div><div><h3 style="margin:0 0 5px">${role==='staff'?'Чат с клиентом':'Алексей · ваш мастер'}</h3><div class="online">● Тестовый чат</div></div></div><div class="chat-messages" id="messages">${o.messages.map(m=>`<div class="bubble ${m.sender===role?'mine':''}">${escapeHTML(m.text)}<small>${m.sender==='staff'?'Мастер':'Клиент'} · ${escapeHTML(m.time)}</small></div>`).join('')}</div><form class="chat-form" id="chat-form"><input id="chat-input" aria-label="Сообщение" placeholder="${role==='staff'?'Ответить клиенту…':'Написать мастеру…'}" maxlength="1000" required><button class="send" aria-label="Отправить сообщение">↑</button></form><p class="tiny" style="margin-top:10px">Демо: сообщения видны в обоих режимах этого браузера.</p></section>`;}
function invoice(o){const total=o.works.reduce((s,w)=>s+w.price,0);return `<section class="card"><h3>Стоимость работ</h3>${o.works.map(w=>`<div class="invoice-row"><span>${escapeHTML(w.title)}</span><strong style="white-space:nowrap">${money(w.price)}</strong></div>`).join('')}<div class="invoice-total"><span>Итого</span><span>${money(total)}</span></div><p class="tiny">Тестовая смета. Оплата на сайте не производится.</p></section>`;}
function bookingsList(staff=false){const list=state.bookings.filter(b=>!b.cancelled);return `<section class="card"><h3>${staff?'Записи клиентов':'Мои записи'} <span class="badge">${list.length}</span></h3>${list.length?list.map(b=>`<div class="booking-item"><strong>${escapeHTML(b.car)}</strong><p class="muted small">${dateLabel(b.date)} · ${b.time}</p><p class="small">${escapeHTML(services.find(s=>s.id===b.service)?.title||'Обслуживание')}</p>${staff?`<p class="tiny">${escapeHTML(b.name)} · ${escapeHTML(b.phone)}${b.comment?' · '+escapeHTML(b.comment):''}</p>`:''}<button class="text-btn" data-cancel="${b.id}">Отменить запись</button></div>`).join(''):'<p class="muted small">Пока нет записей. Выберите удобное время в разделе «Запись».</p>'}</section>`;}
function dashboard(){const o=order();$('#app').innerHTML=pageTop('Ваш автомобиль в заботливых руках','Следите за ремонтом, смотрите фотографии и общайтесь с мастером.')+`<div class="dashboard"><div class="stack">${carCard(o)}${progress(o)}${photos(o)}</div><aside class="stack">${chat(o)}${invoice(o)}<section class="card booking-promo"><div class="eyebrow">ПОЗАБОТЬТЕСЬ ЗАРАНЕЕ</div><h3>Следующее ТО?<br>Выберите удобное время.</h3><p>Покажем свободные окна и запишем вас за пару минут.</p><a href="#booking" class="primary lime full">Записаться в сервис →</a></section>${bookingsList()}</aside></div>`;bindCommon();}
function staff(){const o=order();$('#app').innerHTML=pageTop('Мастерская под контролем','Обновляйте заказ — клиент увидит изменения в своём кабинете.')+`<div class="staff-layout"><aside><h3>Заказы в работе</h3>${state.orders.map(item=>`<button class="order-btn ${o.id===item.id?'selected':''}" data-order="${item.id}"><span class="eyebrow">${item.id}</span><strong style="margin-top:9px">${escapeHTML(item.car)}</strong><span class="badge">${item.accepted?'Принят клиентом':stages[item.stage]}</span><p class="tiny">${item.messages.filter(m=>m.sender==='client').length} сообщений клиента</p></button>`).join('')}</aside><div class="stack">${carCard(o)}<div class="staff-top"><div class="stack"><section class="card"><h3>Обновить статус</h3><form id="status-form"><label>Этап ремонта<select id="status">${stages.map((s,i)=>`<option value="${i}" ${i===o.stage?'selected':''}>${s}</option>`).join('')}</select></label><label>Комментарий для клиента<textarea id="status-note" maxlength="600" required>${escapeHTML(o.note)}</textarea></label><button class="primary full">Сохранить обновление →</button></form>${o.accepted?'<p class="notice">✓ Клиент принял работу. При изменении статуса приёмка будет сброшена.</p>':''}</section><section class="card"><h3>Перечень работ</h3><ul class="work-list">${o.works.map((w,i)=>`<li><label><input type="checkbox" data-work="${i}" ${w.done?'checked':''}>${escapeHTML(w.title)}</label><span class="small">${money(w.price)}</span></li>`).join('')}</ul><form id="work-form"><label>Новая работа<input id="work-title" required maxlength="100" placeholder="Название работы"></label><label>Стоимость, ₽<input id="work-price" type="number" min="0" max="999999" required placeholder="1500"></label><button class="secondary full">+ Добавить работу</button></form></section></div><div class="stack">${chat(o)}${invoice(o)}</div></div>${photos(o,true)}${bookingsList(true)}</div></div>`;bindCommon();
 document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{selectedOrder=b.dataset.order;staff();});
 $('#status-form').onsubmit=e=>{e.preventDefault();const previous=o.stage;o.stage=Number($('#status').value);o.note=$('#status-note').value.trim();if(o.stage!==previous)o.accepted=false;save();staff();toast('Статус обновлён в кабинете клиента');};
 document.querySelectorAll('[data-work]').forEach(c=>c.onchange=()=>{o.works[Number(c.dataset.work)].done=c.checked;save();});
 $('#work-form').onsubmit=e=>{e.preventDefault();const title=$('#work-title').value.trim(),price=Number($('#work-price').value);if(!title||!Number.isFinite(price)||price<0)return;o.works.push({title,price,done:false});save();staff();toast('Работа добавлена в смету');};
 $('#photo-upload').onchange=uploadPhotos;
 document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{o.photos.splice(Number(b.dataset.removePhoto),1);save();staff();toast('Фото удалено');});
}
function bindCommon(){const o=order();bindRoles();document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{const p=o.photos[Number(b.dataset.photo)];$('#large-photo').src=p.src;$('#photo-caption').textContent=p.caption+(p.sample?' · Пример фотографии, не реальный ремонт':'');$('#photo-view').showModal();});if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();const text=$('#chat-input').value.trim();if(!text)return;o.messages.push({sender:role,text,time:'Сегодня, '+now()});save();role==='staff'?staff():dashboard();$('#chat-input').focus();$('#messages').scrollTop=$('#messages').scrollHeight;toast(role==='staff'?'Ответ виден клиенту':'Вопрос добавлен. Ответьте в режиме «Я сотрудник».');};if($('#messages'))$('#messages').scrollTop=$('#messages').scrollHeight;if($('#accept'))$('#accept').onclick=()=>{if(o.stage!==4)return;o.accepted=true;o.messages.push({sender:'client',text:'Я ознакомился с фотоотчётом и принимаю работу. Спасибо!',time:'Сегодня, '+now()});save();dashboard();toast('Работа принята — мастер видит подтверждение');};if($('#ask'))$('#ask').onclick=()=>{$('#chat-card').scrollIntoView({behavior:'smooth',block:'center'});$('#chat-input').focus();};bindCancel();}
function bindRoles(){document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;selectedOrder='AA-2048';if(role==='staff'){location.hash='dashboard';staff();}else render();});}
function bindCancel(){document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const booking=state.bookings.find(x=>x.id===b.dataset.cancel);if(booking){booking.cancelled=true;save();render();toast('Запись отменена. Время снова доступно.');}});}
function booking(){if(role==='staff'){staff();return;}$('#app').innerHTML=pageTop('Запланируйте заботу об автомобиле','Выберите услугу и свободное время. Всё остальное мы берём на себя.')+`<div class="booking-layout"><section class="card"><h2>Запись в мастерскую</h2><form id="booking-form"><div class="fields"><label>Услуга<select id="service">${services.map(s=>`<option value="${s.id}" ${sessionStorage.getItem('service')===s.id?'selected':''}>${s.title}</option>`).join('')}</select></label><label>Дата<input id="date" type="date" min="${dateISO()}" max="${dateISO(30)}" value="${dateISO(1)}" required></label></div><label>Свободное время · Москва</label><div class="slots" id="slots"></div><div class="fields"><label>Ваше имя<input id="booking-name" autocomplete="given-name" placeholder="Например, Анна" required maxlength="60"></label><label>Телефон<input id="booking-phone" type="tel" value="${escapeHTML(state.phone||'')}" placeholder="+7 (999) 123-45-67" required></label></div><label>Автомобиль<input id="booking-car" placeholder="Марка и модель, например Volkswagen Golf" required maxlength="80"></label><label>Что нужно проверить? <span class="muted">Необязательно</span><textarea id="booking-comment" placeholder="Расскажите, что вас беспокоит" maxlength="500"></textarea></label><div class="notice" id="booking-estimate"></div><button class="primary full" style="margin-top:20px" id="book-submit">Подтвердить тестовую запись →</button><p class="tiny" style="margin-top:12px">Запись сохраняется только в этом браузере. Не используйте реальные персональные данные.</p></form></section><aside class="stack"><section class="card booking-promo"><div class="eyebrow">КАК ВСЁ ПРОХОДИТ</div><h3>Без неожиданностей.<br>С заботой о вас.</h3><p>01 · Вы выбираете время<br>02 · Мы диагностируем автомобиль<br>03 · Согласуем работы и стоимость<br>04 · Показываем результат в кабинете</p><p>Тестовый график: ежедневно, 09:00–19:00.<br>Время выделяется с учётом длительности услуги.</p></section>${bookingsList()}</aside></div>`;bindRoles();bindCancel();selectedSlot=null;updateSlots();$('#date').onchange=()=>{selectedSlot=null;updateSlots();};$('#service').onchange=()=>{selectedSlot=null;updateSlots();};$('#booking-form').onsubmit=submitBooking;}
function availableSlots(date,service){const duration=services.find(s=>s.id===service).duration;return Array.from({length:10},(_,i)=>({time:String(9+i).padStart(2,'0')+':00',start:(9+i)*60})).filter(t=>t.start+duration<=19*60).map(t=>{const past=date<dateISO()||(date===dateISO()&&t.time<=now());const blocked=state.bookings.some(b=>!b.cancelled&&b.date===date&&t.start<b.start+b.duration&&t.start+duration>b.start);return {...t,available:!past&&!blocked};});}
function updateSlots(){const service=services.find(s=>s.id===$('#service').value);const date=$('#date').value;$('#slots').innerHTML=availableSlots(date,service.id).map(t=>`<button type="button" class="slot ${selectedSlot===t.time?'selected':''}" data-slot="${t.time}" ${t.available?'':'disabled'}>${t.time}</button>`).join('');$('#booking-estimate').textContent=`Ориентировочно от ${money(service.price)} · ${service.duration/60} ч. Итоговая стоимость согласуется после диагностики.`;document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{selectedSlot=b.dataset.slot;updateSlots();});}
function validPhone(raw){return /^\+?[\d\s()\-]+$/.test(raw)&&raw.replace(/\D/g,'').length>=10&&raw.replace(/\D/g,'').length<=15;}
function submitBooking(e){e.preventDefault();if(!selectedSlot){toast('Выберите свободное время');return;}const date=$('#date').value,service=$('#service').value;if(date<dateISO()||date>dateISO(30)){toast('Выберите дату в ближайшие 30 дней');return;}const slot=availableSlots(date,service).find(s=>s.time===selectedSlot);if(!slot?.available){toast('Это время уже занято. Выберите другое.');updateSlots();return;}const phone=$('#booking-phone').value.trim();if(!validPhone(phone)){toast('Проверьте номер телефона: от 10 до 15 цифр');return;}const name=$('#booking-name').value.trim(),car=$('#booking-car').value.trim();if(!name||!car){toast('Укажите имя и автомобиль');return;}const b={id:crypto.randomUUID(),date,service,time:selectedSlot,start:slot.start,duration:services.find(s=>s.id===service).duration,name,phone,car,comment:$('#booking-comment').value.trim(),cancelled:false};state.bookings.push(b);save();booking();$('#booking-form').before(Object.assign(document.createElement('div'),{className:'success',innerHTML:`<h3>✓ Вы записаны!</h3><p>${dateLabel(b.date)} в ${b.time} · ${escapeHTML(b.car)}</p><p class="small">Тестовая запись также появилась в разделе сотрудников.</p>`}));toast('Тестовая запись создана');}
function servicesPage(){$('#app').innerHTML=pageTop('Честные цены. Понятные услуги.','Сначала согласуем стоимость, затем приступим к работе.')+`<div class="service-grid">${services.map(s=>`<section class="card service-card"><div class="service-icon">${s.icon}</div><h3>${s.title}</h3><p class="muted">${s.description}</p><div class="service-price">от ${money(s.price)}</div><p class="tiny" style="min-height:0;margin-bottom:18px">Ориентировочно ${s.duration/60} ч.</p><button class="secondary full" data-service="${s.id}">Выбрать время →</button></section>`).join('')}</div><p class="notice" style="margin-top:24px">Все цены тестовые. Стоимость запчастей и материалов рассчитывается отдельно, если не указано иначе. Перед ремонтом мастер согласует итоговую смету.</p>`;bindRoles();document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{sessionStorage.setItem('service',b.dataset.service);role='client';location.hash='booking';});}
function reviews(){$('#app').innerHTML=pageTop('Забота, которую замечают','Несколько историй о спокойном и понятном ремонте.')+`<div class="reviews-head"><div class="rating">4,9</div><div><div class="stars">★★★★★</div><p>Пример рейтинга для демонстрации</p><span class="tiny">Все отзывы ниже вымышлены</span></div></div><div class="review-grid">${[{name:'Мария С.',car:'Volkswagen Golf',text:'Наконец-то не приходится звонить и спрашивать, что с машиной. Открыла кабинет — всё видно. Особенно понравились фотографии перед приёмкой.',date:'8 октября 2026'},{name:'Дмитрий К.',car:'Kia Rio',text:'Записался на удобное время, мастер объяснил, что нужно заменить. Стоимость увидел заранее. Всё понятно даже человеку, который не разбирается в машинах.',date:'5 октября 2026'},{name:'Анна В.',car:'Škoda Octavia',text:'Задала вопрос по фото прямо в чате и получила понятный ответ. Забрала автомобиль без волнения. Такой сервис хочется рекомендовать.',date:'1 октября 2026'}].map(r=>`<section class="card"><div class="row"><div class="person"><div class="avatar">${r.name[0]}</div><div><strong>${r.name}</strong><div class="tiny">${r.car}</div></div></div><span class="badge">Демо</span></div><div class="stars" style="margin-top:22px">★★★★★</div><p>${r.text}</p><div class="tiny">${r.date} · Вымышленный отзыв</div></section>`).join('')}</div>`;bindRoles();}
async function uploadPhotos(){const files=[...$('#photo-upload').files],o=order(),caption=$('#photo-title').value.trim()||'Результат выполненной работы';let count=0;for(const file of files){if(o.photos.length>=8){toast('Можно добавить максимум 8 фотографий');break;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){toast('Нужны JPG, PNG или WebP до 8 МБ');continue;}try{const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();o.photos.push({src:canvas.toDataURL('image/jpeg',.75),caption,sample:false});count++;}catch{toast('Не удалось прочитать фотографию');}}save();staff();if(count)toast(`Добавлено фото: ${count}. Они видны клиенту.`);}
function render(){const page=location.hash.slice(1)||'dashboard';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('#account-name').textContent=state.phone?'Кабинет · '+state.phone.replace(/\D/g,'').slice(-4):'Войти по телефону';if(page==='booking')booking();else if(page==='services')servicesPage();else if(page==='reviews')reviews();else role==='staff'?staff():dashboard();}
$('#login-open').onclick=()=>{$('#phone-form').hidden=false;$('#code-form').hidden=true;$('#auth-error').textContent='';$('#phone').value=state.phone||'';$('#auth').showModal();};
$('#phone-form').onsubmit=e=>{e.preventDefault();if(!validPhone($('#phone').value)){$('#auth-error').textContent='Укажите тестовый номер из 10–15 цифр.';return;}$('#auth-error').textContent='';$('#phone-form').hidden=true;$('#code-form').hidden=false;$('#code').value='';$('#code').focus();};
$('#code-form').onsubmit=e=>{e.preventDefault();if($('#code').value!=='1234'){$('#auth-error').textContent='Для демо используйте код 1234.';return;}state.phone=$('#phone').value.trim();save();$('#auth').close();render();toast('Тестовый вход выполнен. Открыт демонстрационный заказ.');};
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#reset').onclick=()=>{if(!confirm('Сбросить тестовые записи, сообщения и фотографии?'))return;state=initial();role='client';selectedOrder='AA-2048';save();render();toast('Демо восстановлено');};
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'smooth'});});
window.addEventListener('storage',e=>{if(e.key==='autoatelier-demo-v1'){try{state=JSON.parse(e.newValue)||initial();render();}catch{}}});
render();
